exercises.starter:
pub fn total(counts: [u32; 4]) -> u32 {
    let mut sum = 0;
    for n in counts.into_iter() {
        sum += *n;
    }
    sum
}

pub fn run() -> u32 {
    total([2, 4, 6, 8])
}

exercises.tests:
#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn sums_the_array() {
        assert_eq!(run(), 20);
        assert_eq!(total([0, 0, 0, 1]), 1);
    }
}

exercises.solution:
pub fn total(counts: [u32; 4]) -> u32 {
    let mut sum = 0;
    for n in counts.into_iter() {
        sum += n;
    }
    sum
}

pub fn run() -> u32 {
    total([2, 4, 6, 8])
}

